@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")  // A01: Access Control
                .anyRequest().authenticated()
            )
            .csrf(csrf -> csrf.disable())  // For stateless REST APIs
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            )
            .headers(headers -> headers
                .contentTypeOptions(withDefaults())  // A05: Security headers
                .xssProtection(withDefaults())
                .frameOptions(frame -> frame.deny())
            );
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();  // A02: Cryptographic Failures prevention
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @Autowired
    private OrderService orderService;

    // Vulnerable: no ownership check
    @GetMapping("/{orderId}")
    public Order getOrderBad(@PathVariable Long orderId) {
        return orderService.findById(orderId);  // Any user can view any order
    }

    // Fixed: verify ownership before returning
    @GetMapping("/{orderId}")
    public Order getOrderSecure(@PathVariable Long orderId, Authentication auth) {
        String currentUser = auth.getName();
        Order order = orderService.findById(orderId);
        if (!order.getCustomerEmail().equals(currentUser)) {
            throw new AccessDeniedException("Not your order");
        }
        return order;
    }

    // Better: use method security with SpEL
    @PreAuthorize("@orderSecurity.isOwner(#orderId, authentication.name)")
    @GetMapping("/{orderId}")
    public Order getOrderBest(@PathVariable Long orderId) {
        return orderService.findById(orderId);
    }
}

