// SecurityConfig.java
@Configuration
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/internal/actuator/**").hasRole("ADMIN")  // Secure Actuator
                .requestMatchers("/h2-console/**").denyAll()  // Block H2 console
                .requestMatchers("/swagger-ui/**", "/v3/api-docs/**")
                    .hasRole("DEVELOPER")  // Require auth for API docs
                .anyRequest().authenticated()
            )
            .headers(headers -> headers
                .contentSecurityPolicy(csp -> csp
                    .policyDirectives("default-src 'self'")  // Restrict resource loading
                )
            );
        return http.build();
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .headers(headers -> headers
                // Spring Security adds these by default:
                .contentTypeOptions(withDefaults())  // X-Content-Type-Options: nosniff
                .xssProtection(withDefaults())       // X-XSS-Protection: 1; mode=block
                .frameOptions(frame -> frame.deny()) // X-Frame-Options: DENY

                // Explicitly configure these:
                .httpStrictTransportSecurity(hsts -> hsts
                    .maxAgeInSeconds(31536000)  // HSTS: 1 year
                    .includeSubDomains(true)
                )
                .contentSecurityPolicy(csp -> csp
                    .policyDirectives("default-src 'self'; script-src 'self'")
                )
                .referrerPolicy(referrer -> referrer
                    .policy(ReferrerPolicy.STRICT_ORIGIN_WHEN_CROSS_ORIGIN)
                )
            )
            .cors(cors -> cors.configurationSource(corsConfigurationSource()));
        return http.build();
    }

    @Bean
    CorsConfigurationSource corsConfigurationSource() {
        var config = new CorsConfiguration();
        config.setAllowedOrigins(List.of("https://trusted-domain.com"));
        config.setAllowedMethods(List.of("GET", "POST"));
        var source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/api/**", config);
        return source;
    }
}
